import{EXESNOHS_CONFIG as h}from"./config.min.js";const d=n=>n*n*(3-2*n),p=n=>1-(1-n)*(1-n);export function contactFraction(n){const t=h.pose.takedown,c=Math.max(0,n-t.close),o=c>0?(n-t.contact)/c:0;if(!(o>0))return t.contactAt.min;if(o>=1)return t.contactAt.max;const e=1-Math.sqrt(1-o);return Math.min(t.contactAt.max,Math.max(t.contactAt.min,e))}export function takedownLength(n=1/0){const t=h.pose.takedown,c=Number.isFinite(n)?contactFraction(n):t.contactAt.max;return Math.max(t.dive,c*t.dive+t.fall)+t.settle}export function takedownAt(n,t,c){const o=h.pose.takedown,e=c.x-t.x,a=c.z-t.z,s=Math.hypot(e,a)||1e-6,x=e/s,l=a/s,m=Math.max(0,s-o.close),i=Math.min(1,Math.max(0,n/o.dive)),u=contactFraction(s)*o.dive,r=Math.min(1,Math.max(0,(n-u)/o.fall)),v=Math.sin(Math.PI*i)*o.leap,y=Math.max(0,1-r*1.6),f=x*o.driven*d(r),M=l*o.driven*d(r);return{tackler:{x:x*m*p(i)+f*o.carry,y:v*y,z:l*m*p(i)+M*o.carry,lean:o.tacklerLean*d(i)},carrier:{x:f,z:M,lean:o.carrierLean*d(r)},contact:n>=u?1:0}}export function tacklerFor(n,t){if(!t)return"";let c="",o=1/0;for(const e of n){if(e===t||e.settings.benched||e.settings.position==="ball"||e.settings.team===t.settings.team)continue;const a=Math.hypot(e.coords.x-t.coords.x,e.coords.y-t.coords.y);a<o&&(o=a,c=e.settings.position)}return c}
